import{a as e,c as t,i as n,t as r}from"./app-B8uz0aqq.js";var i=JSON.parse(`{"path":"/34-Modularization_and_CMake_Plan.html","title":"Apollo 模块化与 CMake 拆分落地方案","lang":"en-US","frontmatter":{},"filePathRelative":"34-Modularization_and_CMake_Plan.md","git":{"createdTime":1773758218000,"updatedTime":1773758218000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"},{"name":"Claude Opus 4.6 (1M context)","username":"","email":"noreply@anthropic.com","commits":1}]}}`),a={name:`34-Modularization_and_CMake_Plan.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="apollo-模块化与-cmake-拆分落地方案" tabindex="-1"><a class="header-anchor" href="#apollo-模块化与-cmake-拆分落地方案"><span>Apollo 模块化与 CMake 拆分落地方案</span></a></h1><h2 id="目标" tabindex="-1"><a class="header-anchor" href="#目标"><span>目标</span></a></h2><p>当前工程已经具备 <code>starter</code>、<code>net</code>、<code>database</code>、<code>redis</code>、<code>game</code> 等方向，但构建层仍以单体 <code>apollo</code> 静态库为主，源码中还存在新旧路径并存的问题，例如：</p><ul><li><code>src/network</code> 与 <code>src/apollo/net</code></li><li><code>src/storage/database</code> 与 <code>src/apollo/database</code></li><li><code>src/apollo/storage/redis</code> 与 <code>src/apollo/redis</code></li></ul><p>这会带来三个直接问题：</p><ol><li>模块边界不清晰，难以按需组装。</li><li>新能力只能继续堆进单体 target。</li><li>应用、框架、业务领域无法稳定分层。</li></ol><p>本方案的目标不是一次性重写，而是在保留现有可构建主干的前提下，引入可增量迁移的模块化骨架。</p><h2 id="分层原则" tabindex="-1"><a class="header-anchor" href="#分层原则"><span>分层原则</span></a></h2><h3 id="base" tabindex="-1"><a class="header-anchor" href="#base"><span><code>base</code></span></a></h3><p>定位：纯基础能力，不携带 Apollo 框架语义。</p><p>放入内容：</p><ul><li>时间、字符串、错误码、结果类型</li><li>buffer、memory pool、lock-free queue</li><li>线程池、基础并发原语</li><li>terminal/console 的底层终端适配</li></ul><p>约束：</p><ul><li>不知道 application、module、service、starter 这些概念</li><li>不依赖 <code>core</code>、<code>runtime</code>、<code>game</code></li></ul><h3 id="core" tabindex="-1"><a class="header-anchor" href="#core"><span><code>core</code></span></a></h3><p>定位：Apollo 框架内核，负责进程内公共运行语义。</p><p>放入内容：</p><ul><li><code>ApplicationContext</code></li><li>配置管理</li><li>日志管理</li><li>生命周期</li><li>事件总线</li><li>模块管理</li><li>指标、服务发现抽象接口</li></ul><p>约束：</p><ul><li>可以依赖 <code>base</code></li><li>不依赖 <code>game</code></li><li>不直接依赖具体 MySQL/Redis/HTTP 实现</li></ul><h3 id="runtime" tabindex="-1"><a class="header-anchor" href="#runtime"><span><code>runtime</code></span></a></h3><p>定位：宿主运行时，负责“程序怎么跑起来”。</p><p>放入内容：</p><ul><li><code>ApplicationHost</code></li><li><code>ServiceHost</code></li><li>tick loop</li><li>shutdown hook</li><li>signal / console event loop</li><li>进程级健康检查</li></ul><p>约束：</p><ul><li>依赖 <code>core</code></li><li>不直接承载具体业务玩法</li></ul><h3 id="net" tabindex="-1"><a class="header-anchor" href="#net"><span><code>net</code></span></a></h3><p>定位：网络能力层，负责收发、协议、连接管理。</p><p>建议拆分：</p><ul><li><code>net/core</code></li><li><code>net/tcp</code></li><li><code>net/http</code></li><li><code>net/websocket</code></li><li><code>net/rpc</code></li></ul><p>约束：</p><ul><li><code>net/core</code> 只放抽象和公共机制</li><li>具体传输协议各自独立</li><li>统一收敛 <code>src/network</code> 与 <code>src/apollo/net</code></li></ul><h3 id="data" tabindex="-1"><a class="header-anchor" href="#data"><span><code>data</code></span></a></h3><p>定位：数据访问层，负责数据库、缓存、序列化接入。</p><p>建议拆分：</p><ul><li><code>data/core</code></li><li><code>data/orm</code></li><li><code>data/redis</code></li></ul><p>语义边界：</p><ul><li><code>data/core</code> 定义 <code>DataSource</code>、<code>Session</code>、<code>Transaction</code>、<code>Repository</code></li><li><code>data/orm</code> 提供 SQL/ORM/MySQL 实现</li><li><code>data/redis</code> 提供 Redis client、cache primitive、排行榜、分布式锁 primitive</li></ul><h3 id="game" tabindex="-1"><a class="header-anchor" href="#game"><span><code>game</code></span></a></h3><p>定位：游戏领域层，按业务语义而不是技术类型拆分。</p><p>建议拆分：</p><ul><li><code>game/core</code></li><li><code>game/world</code></li><li><code>game/battle</code></li><li><code>game/social</code></li><li><code>game/economy</code></li></ul><p>示例：</p><ul><li>AOI、Scene、Map、Movement 放 <code>game/world</code></li><li>Attribute、Skill、Buff、Damage pipeline 放 <code>game/battle</code></li><li>Chat、Guild、Team 放 <code>game/social</code></li></ul><h3 id="starter" tabindex="-1"><a class="header-anchor" href="#starter"><span><code>starter</code></span></a></h3><p>定位：装配层，类似 Spring Boot starter，但采用 C++ 显式注册模式。</p><p>建议拆分：</p><ul><li><code>starter/core</code></li><li><code>starter/net</code></li><li><code>starter/mysql</code></li><li><code>starter/redis</code></li><li><code>starter/game-server</code></li></ul><p>职责：</p><ul><li>判断条件</li><li>注册模块</li><li>注入默认配置</li><li>组合宿主运行时</li></ul><h3 id="apps" tabindex="-1"><a class="header-anchor" href="#apps"><span><code>apps</code></span></a></h3><p>定位：最终可执行程序。</p><p>建议目录：</p><ul><li><code>apps/gateway-server</code></li><li><code>apps/login-server</code></li><li><code>apps/game-server</code></li><li><code>apps/chat-server</code></li></ul><p>职责：</p><ul><li>组合所需 starter / module</li><li>提供进程入口</li><li>注册该程序专属命令和运维接口</li></ul><h2 id="依赖方向" tabindex="-1"><a class="header-anchor" href="#依赖方向"><span>依赖方向</span></a></h2><p>推荐固定如下依赖方向：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">base</span>
<span class="line">  ^</span>
<span class="line">core</span>
<span class="line">  ^</span>
<span class="line">runtime</span>
<span class="line"></span>
<span class="line">net/* ----\\</span>
<span class="line">data/* ----&gt; game/*</span>
<span class="line"></span>
<span class="line">starter/* -&gt; core/runtime/net/data/game</span>
<span class="line">apps/*    -&gt; starter/* + 少量直接模块</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>硬约束：</p><ul><li><code>base</code> 不依赖 Apollo 其他层</li><li><code>core</code> 不依赖 <code>game</code></li><li><code>data</code> 不依赖 <code>game</code></li><li><code>game</code> 不反向进入 <code>core</code></li></ul><h2 id="目录规划" tabindex="-1"><a class="header-anchor" href="#目录规划"><span>目录规划</span></a></h2><p>目标目录如下：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">apollo/</span>
<span class="line">  modules/</span>
<span class="line">    base/</span>
<span class="line">    core/</span>
<span class="line">    runtime/</span>
<span class="line">    net/</span>
<span class="line">      core/</span>
<span class="line">      tcp/</span>
<span class="line">      http/</span>
<span class="line">      websocket/</span>
<span class="line">      rpc/</span>
<span class="line">    data/</span>
<span class="line">      core/</span>
<span class="line">      orm/</span>
<span class="line">      redis/</span>
<span class="line">    game/</span>
<span class="line">      core/</span>
<span class="line">      world/</span>
<span class="line">      battle/</span>
<span class="line">      social/</span>
<span class="line">      economy/</span>
<span class="line">    starter/</span>
<span class="line">      core/</span>
<span class="line">      net/</span>
<span class="line">      mysql/</span>
<span class="line">      redis/</span>
<span class="line">      game-server/</span>
<span class="line">  apps/</span>
<span class="line">    gateway-server/</span>
<span class="line">    login-server/</span>
<span class="line">    game-server/</span>
<span class="line">  tests/</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>说明：</p><ul><li><code>modules/</code> 是新的模块化构建入口</li><li>当前根目录单体 <code>apollo</code> target 暂时保留</li><li>后续每迁移出一个模块，就从根 target 中删掉对应源码</li></ul><h2 id="cmake-目标命名规则" tabindex="-1"><a class="header-anchor" href="#cmake-目标命名规则"><span>CMake 目标命名规则</span></a></h2><p>推荐采用稳定、可预期的 target 名称：</p><ul><li><code>apollo_base</code></li><li><code>apollo_core</code></li><li><code>apollo_runtime</code></li><li><code>apollo_net_core</code></li><li><code>apollo_net_tcp</code></li><li><code>apollo_net_http</code></li><li><code>apollo_net_websocket</code></li><li><code>apollo_net_rpc</code></li><li><code>apollo_data_core</code></li><li><code>apollo_data_orm</code></li><li><code>apollo_data_redis</code></li><li><code>apollo_game_core</code></li><li><code>apollo_game_world</code></li><li><code>apollo_game_battle</code></li><li><code>apollo_starter_core</code></li><li><code>apollo_starter_mysql</code></li><li><code>apollo_starter_redis</code></li></ul><p>这样有三个好处：</p><ol><li>target 名称与目录一一对应。</li><li>依赖关系可读。</li><li>最终 app 的链接清单就是装配清单。</li></ol><h2 id="顶层-cmake-演进策略" tabindex="-1"><a class="header-anchor" href="#顶层-cmake-演进策略"><span>顶层 CMake 演进策略</span></a></h2><p>顶层 <code>CMakeLists.txt</code> 的职责应收敛为：</p><ol><li>定义全局选项和编译标准</li><li>提供现有单体 <code>apollo</code> target</li><li>引入 <code>modules/</code> 和 <code>apps/</code> 两个新入口</li></ol><p>当前阶段采用“骨架先行”策略：</p><ul><li>保留已有 <code>apollo</code> target，避免一次性中断现有开发</li><li>增加 <code>APOLLO_ENABLE_MODULAR_LAYOUT</code></li><li>增加 <code>APOLLO_BUILD_APPS</code></li><li>新建 <code>modules/CMakeLists.txt</code></li><li>新建 <code>apps/CMakeLists.txt</code></li></ul><p>这样后续可以逐个模块迁移，而不是一次性大爆炸式改造。</p><h2 id="模块迁移顺序" tabindex="-1"><a class="header-anchor" href="#模块迁移顺序"><span>模块迁移顺序</span></a></h2><p>推荐按风险从低到高迁移：</p><ol><li><code>base</code></li><li><code>core</code></li><li><code>runtime</code></li><li><code>data/core</code></li><li><code>data/orm</code></li><li><code>data/redis</code></li><li><code>net/core</code></li><li><code>net/tcp/http/websocket/rpc</code></li><li><code>game/core</code></li><li><code>game/world</code></li><li><code>game/battle</code></li><li><code>starter/*</code></li><li><code>apps/*</code></li></ol><p>原因：</p><ul><li>先把底层通用能力稳定下来</li><li>再抽宿主与接入层</li><li>最后迁移强业务语义层</li></ul><h2 id="每个阶段的验收标准" tabindex="-1"><a class="header-anchor" href="#每个阶段的验收标准"><span>每个阶段的验收标准</span></a></h2><h3 id="第一阶段" tabindex="-1"><a class="header-anchor" href="#第一阶段"><span>第一阶段</span></a></h3><ul><li>顶层 CMake 已支持 <code>modules/</code> 和 <code>apps/</code></li><li>架构边界形成文档</li><li>现有单体 target 仍能继续工作</li></ul><h3 id="第二阶段" tabindex="-1"><a class="header-anchor" href="#第二阶段"><span>第二阶段</span></a></h3><ul><li>抽出首批真实模块 target，例如 <code>apollo_base</code>、<code>apollo_core</code></li><li>单元测试可以直接链接模块 target</li></ul><h3 id="第三阶段" tabindex="-1"><a class="header-anchor" href="#第三阶段"><span>第三阶段</span></a></h3><ul><li><code>apps/game-server</code> 能通过 starter/module 组合运行</li><li>根目录单体 <code>apollo</code> target 缩减为兼容聚合 target 或被淘汰</li></ul><h2 id="console-terminal-cli-的归属" tabindex="-1"><a class="header-anchor" href="#console-terminal-cli-的归属"><span>console / terminal / cli 的归属</span></a></h2><p>为了避免把终端适配、控制台事件和运维命令混在一起，建议拆为三层：</p><ul><li><code>modules/base/terminal</code><ul><li>终端输出、颜色、按键、ANSI/Windows 兼容</li></ul></li><li><code>modules/runtime/console</code><ul><li>stdin 监听、Ctrl+C、关闭窗口、console event loop</li></ul></li><li><code>modules/core/cli</code><ul><li>命令注册、参数解析、命令调度</li></ul></li></ul><p>具体业务命令不放公共模块，放到具体 app：</p><ul><li><code>apps/game-server/console</code></li></ul><h2 id="当前仓库下一步建议" tabindex="-1"><a class="header-anchor" href="#当前仓库下一步建议"><span>当前仓库下一步建议</span></a></h2><p>紧接着的落地工作建议是：</p><ol><li>先创建 <code>modules/base</code>、<code>modules/core</code>、<code>modules/runtime</code> 的空 target。</li><li>从旧代码里优先迁移： <ul><li>通用工具类到 <code>base</code></li><li>DI、生命周期、配置、日志到 <code>core</code></li></ul></li><li>新建 <code>apps/game-server</code>，只做最小宿主程序，不承载业务实现。</li><li>将现有 <code>GameServer</code> 从“框架总入口”降级为 runtime/game-server host 的一部分。</li></ol>`,97)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};